"""Post-scoring interpretation only; leaves every frozen artifact untouched."""
from datetime import datetime,timezone
from collections import Counter
from freeze_and_prepare import H,read,save,sha

f=read(H/'METRICS_FROZEN.json')
for p,v in f['files'].items():assert sha(H/p)==v
assert not (H/'ASSESSMENT.json').exists()
rows=read(H/'comparison.json');by={r['cuma_index']:r for r in rows}
routes=read(H/'retrieval_routes.json');rb={r['cuma_index']:r for r in routes}
now=datetime.now(timezone.utc).isoformat();digest=sha(H/'METRICS_FROZEN.json')
assert datetime.fromisoformat(now)>datetime.fromisoformat(f['frozen_at_utc'])

safety={
5684:dict(cause='Source-name constitutional conflict during alias-assisted recovery',explanation='The preferred sulphate claim requires two S=O groups. The accepted sulphite graph has one. A misleading PubChem/supplier name hit and a valid sulphite alias corroborated that different candidate, without resolving which source referent was intended.'),
5997:dict(cause='Relative stereochemistry treated as absolute configuration',explanation='The trans-1,2 preferred name and the alias used for local support specify relative configuration, not the RR/SS choice. The record also contains an RR alias, but its association with the broad preferred referent was not independently established; the engine itself did not promote that RR alias. Frozen reference remains inherently ambiguous.'),
23839:dict(cause='Relative stereochemistry treated as absolute configuration',explanation='Duplicate source concept of 5997, assigned the same RR graph and Substance ID through the same relative-name alias route. It is a second erroneous record, not a second independent chemical failure pattern.'),
30142:dict(cause='Source sugar-form ambiguity hidden by a fully specified candidate graph',explanation='OPSIN selected the open-chain D-glucose-6-phosphate graph. A full-key lookup corroborated that graph but did not establish open-chain rather than cyclic/anomeric source intent. Sodium and water counts were preserved; this is not salt stripping or loss of hydration.')}
cases=[]
for i,detail in safety.items():
    r=by[i];t=rb[i];assert r['exact_verdict']=='INCORRECT'
    cases.append(dict(cuma_index=i,preferred_name=r['preferred_name'],expected=r['expected_status'],predicted=r['predicted_status'],predicted_smiles=r['predicted_smiles'],**detail,routes=t['supporting_increment_routes'],older_path=t['older_path_counterfactual'],reference_evidence=r['evidence']))
increment=[r for r in routes if r['predicted_status']=='EXACT' and r['older_path_counterfactual']=='WOULD_REMAIN_UNRESOLVED']
review=dict(reviewed_at_utc=now,metrics_freeze_sha256=digest,reference_labels_modified=False,primary_metrics_modified=False,
    safety_cases=cases,increment=dict(records=len(increment),verdicts=dict(Counter(r['reference_verdict'] for r in increment)),method='Frozen-trace counterfactual; no old-resolver rerun'),
    methodological_issues=[
        dict(case=24920,issue='Pre-identified sulfinate resonance-enumeration limitation',impact='No effect on admission precision or merges in this run: the record was UNRESOLVED with NO_VALIDATED_CANDIDATE. All 166 reference-EXACT admissions match their frozen full graphs; no graph mismatch was counted as an error.'),
        dict(case=5684,issue='Frozen form-category metadata incorrectly tags a neutral cyclic sulfate/sulfite conflict as salt, protonation_charge and multicomponent',impact='Overall verdict and primary metrics are unchanged. Raw grouped precision contains this category error. A clearly labelled sensitivity view excluding this membership gives salt 3/4, protonation_charge 5/6 and multicomponent 3/4; it is not a reference relabeling.'),
        dict(case=2219,issue='The sole frozen solvate tag is a solution/mixture, not a fixed molecular solvate',impact='There is no established fixed-solvate positive denominator. The frozen OUT_OF_SCOPE reference and CONFLICT prediction remain unchanged.'),
        dict(cases=[51083,45383],issue='Pair diagnostic calls dichloromethane-d2 versus dichloromethane CONSTITUTIONAL_OR_OTHER_FORM_DIFFERENCE',impact='Explicit deuterium becomes explicit hydrogen in the diagnostic isotope-removal view, while the other graph uses implicit hydrogen. Frozen graphs directly establish an isotope difference. Exact comparison correctly kept both admitted forms distinct; no merge or outcome metric changes.'),
        dict(cases=[5684,5997,23839],issue='Alias precision is conditional on an assessable exact subject',impact='All seven unverified promoted aliases belong to false-positive subjects. One is DIFFERENT from the literal preferred sulphate claim; six are relative-stereo names. The 205/205 assessed result must not be presented as validation of all 212 promotions.')],
    supplemental_note='52217 is contradicted as an admissible source-to-identity assignment, not as proof that its literal N-phenyl molecular graph cannot exist.')
save(H/'POST_UNBLINDING_REVIEW.json',review)

ranking=[
 dict(capability='Source-form interpretation before retrieval-assisted admission',confirmed_losses='21 at the source-intent gate; 4 unsafe admissions (3 chemical patterns)',assessment='Safety first: all four new errors and supplemental 52217 concern source intent that a valid retrieved graph cannot settle. The 21 withheld source-intent cases show the opposite, conservative failure mode; they are opportunities, not a recovery promise. Deterministic relative/absolute-stereo, sugar-form and conflicting-name checks can improve this within the existing molecular scope. Reusable for CUMA, CosIng and future sources; implementation change, not relaxed identity policy.'),
 dict(capability='Defined salt and multicomponent semantics, including fixed hydration ratios',confirmed_losses='25 salt-gate losses + 3 hydration-gate losses',assessment='Frequent across unseen names and useful across sources, but an admission expansion would amplify the source-intent risk unless the first capability is addressed. Complete ionic components, proton state and integer ratios offer bounded deterministic checks. Limit to established molecular/composition scope; no automatic acid/base transfer, parent selection or ontology change.'),
 dict(capability='Reliable interpretation of potential stereogenic elements',confirmed_losses='8 stereo-gate losses; at least 2 documented cage false flags',assessment='CUMA 15032 and 44468 establish topology-constrained cage flags; the other six require individual analysis. High risk if a blanket stereo exemption is used. Topology-aware, separately validated treatment is deterministic and source-independent. Identity policy already distinguishes real configuration from representation; no ontology change.'),
 dict(capability='Strict handling of difficult nomenclature and parser warnings',confirmed_losses='17 no-candidate losses + 3 warning-gate losses',assessment='Common across index-style names, markup and malformed spacing; broadly reusable. Conservative typed preprocessing and bounded warning interpretation are implementable, but parser success still cannot prove source intent. No generated aliases or semantic rewriting; within current scope and policy.'),
 dict(capability='Provider-conflict and evidence-lineage attribution',confirmed_losses='9 provider-conflict losses + 3 lineage-gate losses',assessment='False locants, proton states, covalent hydration and correlated sources require discrimination. Provenance and structured contradiction checks are reusable, but a provider majority or more URLs is not evidence independence. Preserve abstention until conflict is explained; no scope or ontology change.'),
 dict(capability='Interpret unresolved identity-dimension diagnostics',confirmed_losses='7 dominant UNKNOWN-dimension losses',assessment='A heterogeneous group including stereo and tautomer issues. Frequency alone does not identify a safe general repair. Improve evidence-level diagnosis before expanding admissions; broadly useful but implementability depends on the specific dimension. Existing semantics can represent the distinctions.'),
 dict(capability='Isotope notation and position interpretation',confirmed_losses='2 records of the same carbon-13 dioxide concept',assessment='A small, duplicated denominator rather than two independent chemical failures. A bounded notation fix is deterministic and within policy; useful for isotope reagents across sources but less central to typical CosIng inputs. Six isotope admissions were correct; positional-isotopologue pair coverage remains absent.'),
 dict(capability='Explicit tautomer evidence reconciliation',confirmed_losses='1 dominant tautomer-conflict loss',assessment='Preserve hydrogen/bond placement when a provider standardizes to another tautomer. Generalizable and within policy, but no paired-tautomer positive denominator here. Twelve adjudicable tautomer-tagged admissions were correct; avoid key-only or parent-tautomer equivalence.'),
 dict(capability='Coordination and inorganic validator scope',confirmed_losses='7 coordination/electronic-state + 4 extended-material gate losses',assessment='Some references establish composition rather than a discrete molecular graph. These losses do not authorize crossing the bounded validator scope. Deterministic support needs domain-specific coordination/electronic-state validation and explicit scope review; applicable to some future material sources, less broadly to molecular CosIng. Parser/provider limitations are not ontology deficiencies.')]

a=dict(assessed_at_utc=now,metrics_freeze_sha256=digest,
 lead='**Safety failures were detected in the retrieval-expanded resolver.** In this 400-record fresh blinded holdout, 171 records were admitted: 166 reference-confirmed, 4 false-positive and 1 unverified. Adjudicable EXACT precision is **166/170 (97.65%)**. All four false-positive records fall in the 26 admissions inferred to require expanded retrieval. The primary next capability is **source-form interpretation before retrieval-assisted admission**, with strict abstention when the source does not establish the candidate’s specificity.',
 sampling_limitations='Eligibility and exclusions were computed before the seeded draw, but their files were serialized with the sample freeze rather than separately timestamped before sampling. This procedural deviation is disclosed; all artifacts were frozen before adjudication. A narrow solvate-name pool was empty, so a source-only solvent/ratio pattern was broadened before freezing. That did not yield established fixed-solvate identities. The reference set has 17 isotope-tagged cases and no INVALID outcome; neither positional-isotopologue nor invalid-input performance is well powered.',
 adjudication_limitations='The references are agent-adjudicated evidence judgments, not experimental measurements or an expert-panel certification. Standalone RDKit, public OPSIN and independently retrieved PubChem evidence were combined with focused regulatory, manufacturer and primary-literature checks. OPSIN/PubChem computational ancestry can overlap with the evaluated engine; upstream independence is often unknown. Some sources were available only as indexed excerpts, and reference-side transport retry histories are incomplete. These limitations and per-record lineage are preserved in each packet’s methodology and evidence cache.',
 overall_interpretation='The four failures represent three chemical patterns because 5997 and 23839 are duplicate source records. None is a mismatch against a frozen reference-EXACT graph: each is an unjustified choice from a conflicting or underspecified referent. All 48 reference out-of-scope records were withheld, although only 22 received the same OUT_OF_SCOPE status. The single unverified admission, 17356, found a full-key PubChem candidate unavailable to the blinded name-based investigation; it was not relabelled after unblinding.',
 form_interpretation='Ordinary molecules performed well (126/126 assessed admissions; 126/138 recall), while stereo-tagged admissions include three unsafe specificity choices. The sole hydrate admission is the glucose-form failure, so 0/1 is not evidence that hydration coefficients were lost. Fixed solvates have no established positive cases. Two frozen category annotations require caution: 5684 is a neutral cyclic sulfate/sulfite conflict, not an ionic salt/multicomponent case; 2219 is a solution. Raw grouped results are retained below; a separate post-unblinding sensitivity view and all methodological issues are explicitly documented, without changing reference labels or primary scores.',
 alias_interpretation='The assessable denominator increased to 205 from 24 in the first fresh holdout (29 in its later upgraded-resolver re-evaluation). However, all seven unverified promotions belong to false-positive subjects: one sulphite alias for 5684 and three relative-stereo aliases on each of 5997 and 23839. The frozen subject-conditional metric excludes them; 100% assessed precision therefore does not establish safety of all promoted aliases. There were 1,410 held alias occurrences, with no automatic promotion from source co-occurrence.',
 near_form_interpretation='Only 3 of 4 coassigned pairs have exact reference identities. The fourth, 5997/23839, repeats the unsafe assignment of one enantiomer to a relative-stereo referent; it is an unassessed merge pair, not evidence of correct clustering or a proven merge of different molecules. The six independently exact-equivalent pairs yielded three correct clusters, two both-withheld pairs and one one-withheld pair. Distinct admissions include D/L-arabinitol, dichloromethane/dichloromethane-d2 and five positional-isomer pairs. Specified/unspecified stereo pairs preserved abstention on the unspecified side. Parent/salt and meropenem/hydrate comparisons mainly withheld a member or both. No tested positive pairs establish safety for positional isotopologues, isolated charge-state variants, different fixed hydration numbers, fixed solvates/different solvents or explicit tautomer pairs. The frozen isotope-pair relation label is overly broad because of explicit-H handling; the molecular graphs and separate IDs correctly retain the isotope distinction.',
 retrieval_interpretation='The trace-based older path was sufficient for 145 admissions, all reference-confirmed. The 26 inferred increment-dependent admissions comprise **21 correct, 4 incorrect and 1 unverified**: **21/25 (84.00%) adjudicable precision**. This shows useful generalization and a safety regression in the expanded admission routes; the counterfactual was not verified by another resolver run. Full-key retrieval supported the glucose-form error; validated-original-alias recovery supported the sulphate/sulphite and two relative-stereo errors. GSRS-supported admissions were 11/11 correct and complete-structure-supported admissions 5/5, with overlapping small denominators. Supplied-identifier lookup was not exercised; alternative validated provider names were queried 30 times but supported no admission. Three correct admissions (9636, 23002, 48151) explicitly rejected distinct full-key discoveries as noncorroborating; these demonstrate safe related-form filtering, not source-intent validation. Nineteen records ended CONFLICT, but none of the four unsafe admissions exposed its source-level problem as a blocking contradiction.',
 execution_limitations='The single run completed successfully in about 28 minutes 25 seconds. Requests used 23.13% of the PubChem budget, 13.18% of ChEBI and 13.25% of GSRS; no budget was exhausted. All 352 cached HTTP failures were 404/not-found responses, with no recorded transport failures. Successful HTTP responses can still contain no candidate or rejected evidence. The new evaluation snapshot contains 167 Substance identities for 171 EXACT reconciliations, four multi-record clusters and 372 stored aliases including preferred names. Existing verify.py revalidated all 171 admissions and found zero duplicate/orphan violations; this tests internal consistency, not chemical correctness.',
 taxonomy_interpretation='The 150 classified items comprise 110 withheld reference-EXACT records, 31 non-admission status disagreements, four reference-uncertainty disagreements, four false-positive admissions and one unverified admission. The table preserves the frozen dominant-gate taxonomy. Detailed safety attribution appears separately below: relative/absolute stereo (2 records), source constitutional conflict (1), sugar-form source intent (1). At least two of the eight stereo-gate losses, 15032 and 44468, have documented topology-related false potential-stereo flags. A no-candidate result does not imply that the reference identity is invalid. Counts are records, not guaranteed recoverable identities or independent chemical examples.',
 supplemental_interpretation='9152 and 46724 match independently established stereodefined structures supported by primary synthetic/patent evidence. 52217 is contradicted as an admissible source-to-identity assignment: the literal N-phenyl preferred name conflicts with substantive N-methyl-d3 aliases and inconsistent marketplace metadata. This does not prove that the literal N-phenyl graph itself is chemically impossible. No supplemental result enters the 400-record metrics, and no earlier reference file was changed.',
 ranked_gaps=ranking,
 primary_next_capability='Source-form interpretation before retrieval-assisted admission',
 recommendation='Require evidence that the original referent supports the chosen constitution and form specificity, separately from proving that a candidate graph exists and parses. In particular, relative stereo must not become absolute through parser defaults, sugar ring/anomer scope must not be inferred from a retrieved open-chain graph, and a validated alias must not repair an unresolved preferred-name conflict. Implement bounded deterministic checks and preserve abstention outside their support. Do not treat every bad alias as a record-level veto; the question is whether the preferred referent itself is established. This is the next development recommendation only; no resolver change was made in this evaluation.',
 ontology_disposition='**No ontology modification is justified by this holdout.** Existing Substance/MolecularSubstance, Alias, Identifier and Structure semantics already distinguish real chemical forms, representational equivalence and unsupported source claims. The failures concern implementation of source intent and evidence scope. Unsupported salt, coordination or solid-state validation does not establish an unrepresentable recurring semantic distinction. No relationship schema or full-CUMA canonicalization is recommended.',
 conclusion='RESOLVER_SAFETY_REGRESSION_DETECTED')
save(H/'ASSESSMENT.json',a)
print('Post-freeze assessment saved; no labels, predictions or primary metrics changed.')
